/**
 * Official links and product photos for the results page (2026-10-11
 * contract, `commerce.ts`). `src/data/mouse-media.json` is generated by
 * `tools/mouse-media/build_media.py`, keyed by mouse slug. A file that does not
 * match the schema, or a slug with no entry, means nothing is shown: this never
 * throws. Pure.
 */
import { z } from "zod";
import { OFFICIAL_URL_KINDS, httpsUrlSchema } from "../contracts/commerce";

export const mouseMediaEntrySchema = z.object({
  officialUrl: httpsUrlSchema,
  officialKind: z.enum(OFFICIAL_URL_KINDS),
  /**
   * `/images/mice/<name>.webp`, or null when no photo exists. Narrower than the
   * fit contract's site-path rule on purpose: a value this accepts is always one
   * `fitResponseSchema` accepts, so a bad file can never make the fit endpoint
   * fail its own response check.
   */
  image: z
    .string()
    .regex(/^\/images\/mice\/[a-z0-9-]+\.webp$/)
    .nullable(),
});
export type MouseMediaEntry = z.infer<typeof mouseMediaEntrySchema>;

/** slug → entry. The slug is a catalogue slug: lowercase words joined by single hyphens. */
export const mouseMediaSchema = z.record(
  z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  mouseMediaEntrySchema,
);
export type MouseMedia = z.infer<typeof mouseMediaSchema>;

/** The entries in `raw`, or `{}` when it is not a valid mouse-media file. */
export function parseMouseMedia(raw: unknown): MouseMedia {
  const parsed = mouseMediaSchema.safeParse(raw);
  return parsed.success ? parsed.data : {};
}

/** The entry for one mouse, or `null` when there is none. */
export function mediaForSlug(
  raw: unknown,
  slug: string,
): MouseMediaEntry | null {
  const media = parseMouseMedia(raw);
  // Own keys only: a slug like "constructor" must not read the prototype.
  return Object.hasOwn(media, slug) ? media[slug] : null;
}

/**
 * The enlarged photo (click to enlarge): same crop window as the 480 px file,
 * so the aspect ratio is the same, 960 px high. Written by
 * `tools/mouse-media/build_media.py --out-large`; the 70 KB per file and
 * 30 MB total budgets are enforced by `tests/unit/mouse-media.test.ts`.
 * `LARGE_PHOTO_WIDTH` is the width the script derives from the shared window;
 * the test reads the real WebP headers against both constants.
 */
export const LARGE_PHOTO_WIDTH = 1109;
export const LARGE_PHOTO_HEIGHT = 960;

const SMALL_PHOTO_PATH = /^\/images\/mice\/([a-z0-9-]+)\.webp$/;

/**
 * `/images/mice/<slug>.webp` → `/images/mice/l/<slug>.webp`. Anything that is
 * not exactly a small-photo path (already a large path, another folder, a
 * query string, a traversal) is returned unchanged, so a bad value can never
 * produce a path outside `/images/mice/l/`. Pure.
 */
export function largePhotoPath(image: string): string {
  const match = SMALL_PHOTO_PATH.exec(image);
  return match ? `/images/mice/l/${match[1]}.webp` : image;
}
